func TestFlattenStringList(t *testing.T) {
	tests := []flattenStringTestCase{
		{
			inputList: starlark.NewList(
				[]starlark.Value{
					starlark.String("a"),
					starlark.String("b"),
				},
			),
			expectedOutput: []string{"a", "b"},
		},
		{
			inputList: starlark.NewList(
				[]starlark.Value{
					starlark.String("a"),
					starlark.NewList(
						[]starlark.Value{
							starlark.String("b"),
						},
					),
				},
			),
			expectedOutput: []string{"a", "b"},
		},
		{
			inputList: starlark.NewList(
				[]starlark.Value{
					starlark.String("a"),
					starlark.NewList(
						[]starlark.Value{
							starlark.String("b"),
							starlark.NewList(
								[]starlark.Value{
									starlark.String("c"),
								},
							),
						},
					),
				},
			),
			expectedOutput: []string{"a", "b", "c"},
		},
		{
			inputList: starlark.NewList(
				[]starlark.Value{
					starlark.NewList(
						[]starlark.Value{
							starlark.String("a"),
							starlark.String("b"),
						},
					),
					starlark.NewList(
						[]starlark.Value{
							starlark.String("c"),
							starlark.String("d"),
