type assertTestCase interface {
	ExpFailure() bool
	ExpFailureMsg() string
	ExpError() bool
	ExpErrorMsg() string
}

type assertTestCaseImpl struct {
	expFailure    bool
	expFailureMsg string
	expError      bool
	expErrorMsg   string
}

func (a assertTestCaseImpl) ExpFailure() bool      { return a.expFailure }
func (a assertTestCaseImpl) ExpFailureMsg() string { return a.expFailureMsg }
func (a assertTestCaseImpl) ExpError() bool        { return a.expError }
func (a assertTestCaseImpl) ExpErrorMsg() string   { return a.expErrorMsg }

type assertBinaryTestCase struct {
	assertTestCaseImpl
	op      syntax.Token
	val1Str string
	val2Str string
	msg     string
}

type assertUnaryTestCase struct {
	assertTestCaseImpl
	val string
	msg string
}

func TestUnaryAsserts(t *testing.T) {
	testCases := []assertUnaryTestCase{
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure: false,
				expError:   false,
			},
			val: `1 == 1`,
		},
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure: false,
				expError:   false,
			},
			val: `1 == 1`,
			msg: "unary assertion error message",
		},
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure:    true,
				expFailureMsg: "assertion failed",
				expError:      false,
			},
			val: `2 == 1`,
		},
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure:    true,
				expFailureMsg: "assertion failed: unary assertion error message",
				expError:      false,
			},
			val: `2 == 1`,
			msg: "unary assertion error message",
		},
	}

	for _, testCase := range testCases {
		cmd := fmt.Sprintf(
			`t.assert(%s)`,
			testCase.val,
		)

		if testCase.msg != "" {
			cmd = fmt.Sprintf(
				`t.assert(%s, %q)`,
				testCase.val,
				testCase.msg,
			)
		}

		evalAndReportResults(t, cmd, testCase)
	}
}

