				expErrorMsg: "int >= string not implemented",
			},
		},
	}

	for _, testCase := range testCases {
		cmd := fmt.Sprintf(
			`t.assert.%s(%s, %s)`,
			tokenToString[testCase.op],
			testCase.val1Str,
			testCase.val2Str,
		)

		if testCase.msg != "" {
			cmd = fmt.Sprintf(
				`t.assert.%s(%s, %s, %q)`,
				tokenToString[testCase.op],
				testCase.val1Str,
				testCase.val2Str,
				testCase.msg,
