func TestAssertFails(t *testing.T) {
	testCases := []assertUnaryTestCase{
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure: false,
				expError:   false,
			},
			val: `fail, "this is an expected failure"`,
		},
		assertUnaryTestCase{
