				expFailureMsg: "assertion failed: function print should have failed",
				expError:      false,
			},
			val: `print, "this should have failed"`,
		},
		assertUnaryTestCase{
			assertTestCaseImpl: assertTestCaseImpl{
				expFailure:  false,
				expError:    true,
