func TestMessageAttrNames(t *testing.T) {
	t.Parallel()

	val, err := eval(`proto.package("skycfg.test_proto").MessageV3()`, nil)
	if err != nil {
		t.Fatal(err)
	}
	got := val.(starlark.HasAttrs).AttrNames()
	want := []string{
		"assert_",
		"f_int32",
		"f_int64",
		"f_uint32",
		"f_uint64",
		"f_float32",
		"f_float64",
		"f_string",
		"f_bool",
		"f_submsg",
		"r_string",
		"r_submsg",
		"map_string",
		"map_submsg",
		"f_nested_submsg",
		"f_toplevel_enum",
		"f_nested_enum",
		"f_oneof_a",
		"f_oneof_b",
		"f_bytes",
		"f_BoolValue",
		"f_StringValue",
		"f_DoubleValue",
		"f_Int32Value",
		"f_Int64Value",
		"f_BytesValue",
		"f_Uint32Value",
		"f_Uint64Value",
		"r_StringValue",
		"f_Any",
		"pass_",
		"return_",
		"safe_",
	}
	sort.Strings(want)
	if !reflect.DeepEqual(want, got) {
